from __future__ import annotations

BASE_STYLE = """
<style>
:root{--bg:#f7f8fb;--panel:#fff;--text:#101828;--muted:#667085;--border:#e4e7ec;--blue:#3b82f6;--green:#12b76a;--orange:#f79009;--red:#f04438;--purple:#7c3aed;--shadow:0 18px 45px rgba(16,24,40,.08)}
*{box-sizing:border-box}body{margin:0;min-width:1280px;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.app{display:grid;grid-template-columns:248px 1fr;min-height:100vh}.nav{background:#fff;border-right:1px solid var(--border);padding:28px 22px}.nav h1{font-size:20px;margin:0 0 24px}.nav a{display:block;padding:10px 12px;border-radius:10px;color:#344054;text-decoration:none;margin:4px 0}.nav a.active,.nav a:hover{background:#eff6ff;color:#1d4ed8}.main{padding:32px 40px}.top{display:flex;justify-content:space-between;align-items:center}.btn{border:0;border-radius:10px;padding:9px 14px;font-weight:700;cursor:pointer}.primary{background:var(--blue);color:#fff}.secondary{background:#f2f4f7;color:#344054}.success{background:var(--green);color:#fff}.warning{background:var(--orange);color:#fff}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:24px 0}.metric{background:#fff;border:1px solid var(--border);border-radius:16px;padding:16px;box-shadow:var(--shadow);cursor:pointer}.metric.active{border-color:var(--blue);box-shadow:0 0 0 3px #eff6ff}.metric strong{display:block;font-size:28px;margin-top:6px}.panel{background:#fff;border:1px solid var(--border);border-radius:18px;box-shadow:var(--shadow)}.content{display:grid;grid-template-columns:minmax(0,1fr) minmax(420px,480px);gap:20px;align-items:start}.toolbar{display:flex;gap:10px;margin:0 0 14px}.input,textarea,select{border:1px solid var(--border);border-radius:10px;padding:10px;font:14px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid var(--border);text-align:left;font-size:14px}th{background:#f9fafb;color:#344054}.pill{display:inline-block;border-radius:999px;padding:4px 10px;font-size:12px;font-weight:700;background:#eff6ff;color:#1d4ed8}.drawer{padding:18px;min-height:620px;overflow:hidden}.drawer pre{max-width:100%;overflow:auto;white-space:pre-wrap}.stages{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin:14px 0}.stage{text-align:center;border:1px solid var(--border);border-radius:12px;padding:8px 6px;font-size:12px;background:#fff;white-space:normal;line-height:1.25}.stage.active{border-color:var(--blue);background:#eff6ff;color:#1d4ed8;font-weight:700}.muted{color:var(--muted)}.modal-mask{position:fixed;inset:0;background:rgba(16,24,40,.35);display:none;align-items:center;justify-content:center}.modal{width:620px;background:#fff;border-radius:20px;padding:24px;box-shadow:var(--shadow)}.modal label{display:block;font-weight:700;margin:12px 0 6px}.modal input,.modal textarea{width:100%}.actions{display:flex;gap:10px;justify-content:flex-end;margin-top:18px}pre{white-space:pre-wrap;background:#101828;color:#d0d5dd;border-radius:14px;padding:16px;overflow:auto;font-size:12px}.stages{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:14px 0}.stage{border:1px solid var(--border);border-radius:12px;padding:10px;font-size:12px;background:#fff}.stage.active{border-color:var(--blue);background:#eff6ff}
</style>
"""
